window.createIntelligence=function(api){
  const e=api.esc,$=s=>document.querySelector(s),M=IntelligenceModel,R=ModelRegistry;
  let mode='standard',token='',connector=null,config=null,ready=false,connecting=null,scope='auto',pending=null,epoch=0,switchVersion=0,assistantDraft='',requestError='',startup=false;
  let activeConversation=M.conversationId(api.getState().aiMessages.at(-1)||{conversationId:crypto.randomUUID()});
  scope=M.conversations(api.getState().aiMessages).find(g=>g.id===activeConversation)?.scope||'auto';
  const drafts=new Map();
  const currentMessages=()=>M.conversation(api.getState().aiMessages,activeConversation);
  function rememberDraft(){drafts.set(activeConversation,{text:assistantDraft,scope});}
  function selectConversation(id){if(pending)return;rememberDraft();activeConversation=id;const saved=drafts.get(id),group=M.conversations(api.getState().aiMessages).find(g=>g.id===id);assistantDraft=saved?.text||'';scope=saved?.scope||group?.scope||'auto';requestError='';api.refresh();}
  function newConversation(nextScope='auto',text=''){if(pending)return false;rememberDraft();activeConversation=crypto.randomUUID();scope=nextScope;assistantDraft=text;requestError='';return true;}
  const prefKey='yuanliu-mode-preference';
  const modeDialog=document.createElement('dialog');modeDialog.id='mode-dialog';modeDialog.className='intelligence-dialog';document.body.append(modeDialog);
  const configDialog=document.createElement('dialog');configDialog.id='model-dialog';configDialog.className='intelligence-dialog';document.body.append(configDialog);
  function pref(){try{return JSON.parse(localStorage.getItem(prefKey)||'null');}catch{return null;}}
  async function connectLocal(){
    if(ready)return;if(connecting)return connecting;
    connecting=(async()=>{if(location.protocol==='file:')throw Error('智能模式需要通过本机链接打开，请运行「启动源流.command」。');let response;try{response=await fetch('/api/model/session',{cache:'no-store',signal:AbortSignal.timeout(5000)});}catch{throw Error('无法连接本机模型网关，请运行「启动源流.command」后重试。');}if(!response.ok)throw Error('请重启本机服务后使用智能模式。');const status=await response.json();if(!status.token)throw Error('本机模型网关需要更新，请重启后再试。');token=status.token;connector=ModelConnector.createModelConnector({sessionToken:token});ready=true;})();
    try{return await connecting;}finally{connecting=null;}
  }
  const smart=()=>mode==='smart',connected=()=>!!connector?.isConnected();
  function refresh(){document.documentElement.dataset.mode=mode;const button=$('#mode-switch');if(button)button.innerHTML=`<i></i>${smart()?'智能模式':'标准模式'}`;api.refresh();}
  function stop(){epoch++;if(pending){pending.abort();pending=null;}requestError='';}
  async function choose(next,remember){
    const version=++switchVersion;if(next==='smart'){try{await connectLocal();if(version!==switchVersion)return;if(!connected()){openConfig(true);return;}}catch(err){const p=modeDialog.querySelector('[role=alert]');if(p)p.textContent=err.message;else api.toast(err.message);return;}}else stop();
    if(version!==switchVersion)return;mode=next;try{if(remember)localStorage.setItem(prefKey,JSON.stringify({mode:next}));else localStorage.removeItem(prefKey);}catch{}modeDialog.close();startup=false;refresh();
  }
  function openMode(isStartup=false){
    startup=isStartup;const saved=pref();
    modeDialog.innerHTML=`<div class="dialog-head"><span class="eyebrow">YUANLIU · YOUR WORKSPACE</span><button class="close" type="button" data-mode-close aria-label="关闭模式选择">×</button></div><h2 id="mode-title">以你的方式，开始。</h2><p class="subtitle">同一份工作，两种节奏。随时可以切换。</p><div class="mode-options"><button class="mode-option" data-pick-mode="standard"><span class="mode-glyph">◷</span><strong>标准模式</strong><p>收拢灵感，安排日程，推进项目。<br>直接打开，专注手上的事。</p><span class="mode-enter">进入工作台 <b>→</b></span></button><button class="mode-option smart-option" data-pick-mode="smart"><span class="mode-glyph">✦</span><strong>智能模式</strong><p>连接你自己的大模型，<br>让 AI 协助整理、分析与总结。</p><span class="mode-enter">${connected()?'开启并进入':'连接并进入'} <b>→</b></span></button></div><label class="mode-remember"><input id="remember-mode" type="checkbox" ${saved?'checked':''}> 下次直接使用所选模式</label><p class="mode-footnote">API Key 只保留在当前页面内存中，刷新或关闭页面后需要重新连接。</p><p class="error" role="alert"></p>`;
    modeDialog.setAttribute('aria-labelledby','mode-title');if(!modeDialog.open)modeDialog.showModal();
  }
  function settings(){return `<section class="model-settings-strip"><div><h2>工作模式与模型连接</h2><p>${smart()?'智能模式已开启':'当前为标准模式'} · ${connected()?e(config.providerName)+' / '+e(config.tierLabel)+' / '+e(config.model):'尚未连接模型'}</p></div><div><button class="button" data-open-mode>切换模式</button><button class="button soft" data-open-model>${connected()?'管理连接':'连接模型'}</button></div></section>`;}
  function openConfig(enableAfter=false){
    const rememberAfter=$('#remember-mode')?.checked??(pref()?.mode==='smart'),initialProvider=config?.provider||'deepseek',initialTier=config?.tier||'balanced';
    const providerOptions=R.providers.map(p=>`<option value="${p.id}" ${p.id===initialProvider?'selected':''}>${e(p.name)}</option>`).join(''),tierOptions=Object.values(R.tiers).map(t=>`<option value="${t.id}" ${t.id===initialTier?'selected':''}>${e(t.name)}${t.recommended?' · 推荐':''}</option>`).join('');
    configDialog.innerHTML=`<form id="model-form"><div class="dialog-head"><div><span class="eyebrow">YOUR MODEL · YOUR KEY</span><h2 id="model-title">连接你的大模型</h2></div><button class="close" type="button" data-model-close aria-label="关闭模型连接">×</button></div><p class="subtitle">选择服务商和质量档位，源流会透明显示实际调用的模型。</p><div class="model-choice-grid"><label class="field">服务商<select name="provider">${providerOptions}</select></label><label class="field">质量档位<select name="tier">${tierOptions}</select></label></div><div id="model-resolution" class="model-resolution" aria-live="polite"></div><label class="field">API Key<div class="model-key-row"><input name="apiKey" type="password" autocomplete="off" spellcheck="false" required placeholder="输入你自己的 API Key"><button type="button" class="text-button" data-key-visibility>显示</button></div></label><details class="model-advanced"><summary>高级设置</summary><p class="meta">只有服务商使用专属地址、模型别名或兼容接口时才需要修改。</p><label class="field">API 地址<input name="baseUrl" type="url" required></label><label class="field">模型 ID<input name="model" required maxlength="160"></label></details><p class="model-key-note">Key 仅保存在当前页面内存中，不写入浏览器存储、项目备份、URL、日志或源代码。页面刷新后需要重新填写。</p><p class="meta">连接测试会向所选服务商发送一句“只回复：连接成功”，不发送工作内容；服务商可能按调用计费。</p><p class="error" role="alert"></p><div class="dialog-actions">${connected()?'<button type="button" class="text-button" data-model-disconnect>断开当前连接</button>':''}<button class="button" type="button" data-model-close>取消</button><button class="button primary" type="submit">测试并连接${enableAfter?'，开启智能模式':''}</button></div></form>`;
    configDialog.setAttribute('aria-labelledby','model-title');if(!configDialog.open)configDialog.showModal();const form=configDialog.querySelector('form'),advanced=form.querySelector('.model-advanced');
    function updateResolution(resetFields=true){const preset=R.resolveProviderTier(form.elements.provider.value,form.elements.tier.value),provider=R.getProvider(preset.provider);if(resetFields){form.elements.baseUrl.value=preset.baseUrl;form.elements.model.value=preset.model;}const actual=form.elements.model.value||'等待填写模型 ID';form.querySelector('#model-resolution').innerHTML=`<div><span>实际调用</span><strong>${e(actual)}</strong><small>${e(preset.detail)}</small></div>${preset.docs?`<a href="${e(preset.docs)}" target="_blank" rel="noopener noreferrer">官方文档</a>`:''}`;if(provider.requiresModel)advanced.open=true;}
    form.elements.provider.onchange=()=>{form.elements.apiKey.value='';updateResolution(true);form.querySelector('[role=alert]').textContent='';};form.elements.tier.onchange=()=>updateResolution(true);form.elements.model.oninput=()=>updateResolution(false);
    form.querySelector('[data-key-visibility]').onclick=event=>{const key=form.elements.apiKey,show=key.type==='password';key.type=show?'text':'password';event.currentTarget.textContent=show?'隐藏':'显示';};updateResolution(true);
    form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='正在进行真实连接测试…';form.querySelector('[role=alert]').textContent='';try{await connectLocal();const values=Object.fromEntries(new FormData(form));config=await connector.connect(values);form.elements.apiKey.value='';const stillOpen=configDialog.open&&configDialog.querySelector('form')===form;if(stillOpen)configDialog.close();if(enableAfter&&stillOpen)await choose('smart',rememberAfter);else{refresh();api.toast('模型已连接；刷新页面后需要重新连接');}}catch(error){form.querySelector('[role=alert]').textContent=error.message;}finally{submit.disabled=false;submit.textContent='测试并连接'+(enableAfter?'，开启智能模式':'');}};
  }
  function buildContext(){return M.context(api.getState(),{scope,today:api.today(),modules:api.modules});}
  function preview(){try{const c=buildContext(),history=currentMessages().map(x=>x.message),included=(M.messages(c,assistantDraft||'继续',history).length-2)/2,total=history.filter(m=>m.role==='user').length;return `<details class="ai-context-preview"><summary>回答前读取：${c.memories.length} 条长期记忆 · ${c.projects.length} 个项目 · ${c.tasks.length} 项任务 · ${c.events.length} 场日程</summary><p>长期记忆与所选当前工作会自动发送；本次同时带上当前对话最近 ${included} 轮${total>included?`（共 ${total} 轮，较早内容不发送）`:""}；文档只提供名称。切换工作范围会开启新对话。展开可核对本次工作上下文。</p><pre>${e(JSON.stringify(c,null,2))}</pre></details>`;}catch(err){return `<p class="error">${e(err.message)}</p>`;}}
  function assistant(messages){
    const groups=M.conversations(api.getState().aiMessages);for(const [id,draft] of drafts){if(draft.text&&!groups.some(g=>g.id===id))groups.unshift({id,title:draft.text.slice(0,26)+'（草稿）'});}if(!groups.some(g=>g.id===activeConversation))groups.unshift({id:activeConversation,title:'新对话'});const isSmart=smart(),modelLabel=config?config.providerName+' · '+config.tierLabel+' · '+config.model:'';
    return `<div class="page-heading"><div><h1>${isSmart?'AI 助理':'助理记录'}</h1></div>${!isSmart?'<button class="button primary" data-open-mode>开启智能模式</button>':''}</div><div class="ai-layout"><section class="ai-chat"><div class="ai-chat-head"><span class="ai-orb">✦</span><div><h2>源流助理</h2><p>${isSmart?e(modelLabel)+' · 长短期上下文已启用':'标准模式 · 历史记录可继续查看'}</p></div></div><div class="ai-conversation-bar"><label>对话<select id="ai-conversation" aria-label="选择对话" ${pending?'disabled':''}>${groups.map(g=>`<option value="${e(g.id)}" ${g.id===activeConversation?'selected':''}>${e(g.title)}</option>`).join('')}</select></label><button class="button" type="button" data-ai-new ${pending?'disabled':''}>新对话</button></div><div class="ai-messages">${messages||'<div class="ai-welcome"><h3>从你正在做的事开始。</h3><p>我会先读取长期记忆与当前项目，再结合你的问题回答或规划。</p></div>'}${pending?'<p class="ai-loading" role="status">正在读取上下文并整理思路… <button class="text-button" data-ai-stop>停止等待</button></p>':''}</div>${isSmart?`<form id="ai-form" class="ai-composer"><div class="ai-context-controls"><label>当前工作范围<select id="ai-scope" ${pending?'disabled':''}><option value="auto" ${scope==='auto'?'selected':''}>自动关联进行中的工作</option><option value="today" ${scope==='today'?'selected':''}>聚焦今天</option><option value="all" ${scope==='all'?'selected':''}>全部工作记录</option>${api.getState().projects.map(p=>`<option value="project:${e(p.id)}" ${scope==='project:'+p.id?'selected':''}>聚焦项目：${e(p.title)}</option>`).join('')}</select></label><span class="ai-memory-check ai-memory-auto">◉ 长期记忆自动读取</span></div><div id="ai-context-preview">${preview()}</div><textarea id="ai-input" maxlength="8000" required placeholder="例如：结合我的工作原则和当前项目，帮我规划下一步" aria-label="和 AI 助理对话" ${pending?'disabled':''}>${e(assistantDraft)}</textarea><p class="error" role="alert">${e(requestError)}</p><div class="ai-compose-foot"><span>发送至 ${e(config.model)} · 新建事项确认后保存</span><button class="button primary" type="submit" ${pending?'disabled':''}>${requestError?'重试发送':'发送给助理'}</button></div></form>`:''}</section><aside class="ai-examples"><a class="memory-assistant-entry" href="#memory">工作记忆 <span>维护职责、偏好、规则、背景与决定 →</span></a><h3>让助理搭一把手</h3>${isSmart?'<button class="example" data-smart-preset="today">帮我排今天的优先级</button><button class="example" data-smart-preset="summary">生成一份工作总结</button><button class="example" data-smart-preset="draft">整理一项任务</button>':'<p>标准模式下，可以直接添加任务、日程和项目。</p>'}<div class="ai-note">${isSmart?'每次回答都会读取已确认的长期记忆和所选当前工作；发送内容可在上方展开核对。同一对话最多带上最近 6 轮，较早内容仍保留可查看；不同对话彼此隔离，在线文档正文不会自动发送。':'你的工作台可以独立使用，无需配置大模型。'}</div></aside></div>`;
  }
  async function send(text){if(!smart()){openMode();return;}if(pending)return;const t=text.trim();if(!t)return;assistantDraft=t;let ctx,requestMessages;try{ctx=buildContext();requestMessages=M.messages(ctx,t,currentMessages().map(x=>x.message));}catch(err){requestError=err.message;api.refresh();return;}const controller=new AbortController(),version=++epoch;pending=controller;requestError='';api.refresh();const timeout=setTimeout(()=>controller.abort(),120000);try{const result=await connector.chat({messages:requestMessages,maxTokens:6000,responseSchema:M.responseSchema},controller.signal);if(version!==epoch||!smart())return;const answer=M.answer(result.content,ctx);const ok=api.commit(next=>{next.aiMessages.push({id:crypto.randomUUID(),conversationId:activeConversation,role:'user',text:t,sourceScope:ctx.scope,createdAt:new Date().toISOString()},{id:crypto.randomUUID(),conversationId:activeConversation,role:'assistant',text:answer.text,action:answer.action,suggestions:answer.suggestions||[],providerModel:result.model||config.model,sourceScope:ctx.scope,createdAt:new Date().toISOString()});});if(!ok)throw Error('回复未能保存，输入已保留，请检查浏览器存储空间。');assistantDraft='';}catch(err){if(version===epoch)requestError=err.name==='AbortError'?'等待已结束，输入内容已保留。服务商可能仍在处理刚才的请求。':err.message;}finally{clearTimeout(timeout);if(version===epoch){pending=null;if(api.isAssistant())api.refresh();else api.toast(requestError||'助理回复已保存，可打开查看');}}}
  function compose(text){if(!smart()){openMode();return false;}if(pending){api.toast('请等待当前请求完成，或先停止等待');return false;}newConversation('auto',text);api.navigate('#assistant');$('#ai-input')?.focus();return true;}
  function prepare(kind,projectId='',moduleId=''){if(!smart()){openMode();return;}if(pending){api.toast('请等待当前请求完成，或先停止等待');return;}newConversation(projectId?'project:'+projectId:kind==='today'?'today':kind==='summary'?'all':'auto');assistantDraft=kind==='today'?'根据今天的任务与日程，建议优先级和安排，并说明理由。':kind==='summary'?'根据参考记录生成工作总结，区分已完成、进行中、阻塞和下一步；没有完成日期的内容不要归为本周成果。':kind==='project'?'分析这个项目的进展、风险和阻塞，并给出下一步建议。':kind==='module'?'针对项目模块「'+(api.modules(api.getState().projects.find(p=>p.id===projectId)).find(m=>m.id===moduleId)?.title||moduleId)+'」建议接下来的具体任务，先给建议清单。':'请帮我新增一项任务：';requestError='';api.navigate('#assistant');$('#ai-input')?.focus();}
  document.addEventListener('click',event=>{if(event.target.closest('[data-ai-open-source]')){const id=event.target.closest('[data-ai-open-source]').dataset.aiOpenSource,index=api.getState().aiMessages.findIndex((m,i)=>(m.id||'legacy:'+i)===id);if(index<0){api.toast('原对话记录已不存在');return;}if(pending){api.toast('请先等待当前对话完成');return;}$('#editor')?.close();selectConversation(M.conversationId(api.getState().aiMessages[index]));api.navigate('#assistant');$(`[data-ai-message="${index}"]`)?.scrollIntoView({block:'center'});return;}if(event.target.closest('[data-ai-new]')){if(newConversation())api.refresh();return;}if(event.target.closest('[data-open-mode],#mode-switch'))return openMode();if(event.target.closest('[data-open-model]'))return openConfig();if(event.target.closest('[data-mode-close]')){switchVersion++;modeDialog.close();startup=false;return;}if(event.target.closest('[data-model-close]')){configDialog.close();const field=configDialog.querySelector('[name=apiKey]');if(field)field.value='';return;}const pick=event.target.closest('[data-pick-mode]');if(pick)return choose(pick.dataset.pickMode,!!$('#remember-mode')?.checked);const preset=event.target.closest('[data-smart-preset]');if(preset)return prepare(preset.dataset.smartPreset,preset.dataset.smartProject||'',preset.dataset.smartModule||'');if(event.target.closest('[data-ai-stop]')){stop();requestError='已停止等待。服务商可能仍在处理刚才的请求；输入内容已保留。';api.refresh();return;}if(event.target.closest('[data-ai-copy]')){const m=api.getState().aiMessages[Number(event.target.closest('[data-ai-copy]').dataset.aiCopy)];if(m)navigator.clipboard.writeText([m.text,...(m.suggestions||[]).map((s,n)=>`${n+1}. ${s.data.title}${s.confirmed?'（已加入任务）':''}${s.data.description?'\n'+s.data.description:''}${s.data.plannedDate?'\n计划：'+s.data.plannedDate:''}${s.data.due?'\n截止：'+s.data.due:''}`)].join('\n\n')).then(()=>api.toast('已复制回复')).catch(()=>api.toast('复制失败，可以直接选择回复文本复制'));}if(event.target.closest('[data-model-disconnect]')){connector?.disconnect();config=null;stop();mode='standard';configDialog.close();refresh();api.toast('模型连接已断开，已回到标准模式');}});
  document.addEventListener('keydown',event=>{if(event.target.id==='ai-input'&&(event.metaKey||event.ctrlKey)&&event.key==='Enter'&&!event.isComposing){event.preventDefault();$('#ai-form')?.requestSubmit();}});document.addEventListener('input',event=>{if(event.target.id==='ai-input')assistantDraft=event.target.value;});document.addEventListener('change',event=>{if(event.target.id==='ai-conversation'){selectConversation(event.target.value);return;}if(event.target.id!=='ai-scope')return;const nextScope=event.target.value;if(currentMessages().length){newConversation(nextScope,assistantDraft);api.refresh();api.toast('已按新的工作范围开启对话，原对话仍可查看');}else{scope=nextScope;$('#ai-context-preview').innerHTML=preview();}});modeDialog.addEventListener('close',()=>{startup=false;});configDialog.addEventListener('close',()=>{const field=configDialog.querySelector('[name=apiKey]');if(field)field.value='';});
  function init(){const saved=pref();if(!saved)openMode(true);connectLocal().then(()=>{if(saved?.mode==='smart'&&switchVersion===0)choose('smart',true);}).catch(()=>{if(saved?.mode==='smart'&&switchVersion===0)openMode(true);});document.documentElement.dataset.mode=mode;}
  function fromHome(text){if(pending){api.toast('助理正在处理上一条需求，请稍后再试');return false;}newConversation('auto',text);api.navigate('#assistant');$('#ai-input')?.focus();return true;}
  return {currentMessages,smart,settings,assistant,send,compose,prepare,init,openMode,fromHome,model:()=>config?.model||''};
};
